"use client";

import { Check, FileText, LoaderCircle } from "lucide-react";
import { useCrate } from "./crate-provider";
import { cx, type WaitStateProps } from "./types";

export type FileStage = "uploading" | "reading" | "chunking" | "ready";
export type FileProcessingProps = WaitStateProps & { filename: string; size: string; stage?: FileStage; progress?: number };

const stages: Array<{ key: FileStage; label: "fileUploading" | "fileReading" | "fileChunking" | "fileReady" }> = [
  { key: "uploading", label: "fileUploading" },
  { key: "reading", label: "fileReading" },
  { key: "chunking", label: "fileChunking" },
  { key: "ready", label: "fileReady" },
];

export function FileProcessing({ className, accent = false, filename, size, stage = "uploading", progress = 0, labels }: FileProcessingProps) {
  const { labels: l, format } = useCrate(labels);
  const activeIndex = stages.findIndex((item) => item.key === stage);
  const percent = stage === "ready" ? 100 : Math.max(0, Math.min(100, progress));
  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} aria-live="polite">
      <div className="flex items-center gap-3"><span className={cx("grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><FileText className="size-4" /></span><div className="min-w-0 flex-1"><p className="m-0 truncate text-sm font-medium">{filename}</p><p className="m-0 text-xs text-muted-foreground">{size}</p></div><span className="text-xs text-muted-foreground">{l.fileProgress(percent, format)}</span></div>
      <div className="my-3 h-1.5 overflow-hidden rounded-full bg-muted" aria-hidden="true"><span className={cx("block h-full rounded-full bg-muted-foreground transition-[width] motion-reduce:transition-none", accent && "bg-primary")} style={{ width: `${percent}%` }} /></div>
      <ol className="grid grid-cols-4 gap-1 text-center text-[10px] text-muted-foreground">
        {stages.map((item, index) => <li key={item.key} className={cx("flex min-w-0 flex-col items-center gap-1", index === activeIndex && "text-foreground")}><span className={cx("grid size-5 place-items-center rounded-full border border-border", index === activeIndex && accent && "border-primary text-primary")} aria-hidden="true">{index < activeIndex || stage === "ready" ? <Check className="size-3" /> : index === activeIndex ? <LoaderCircle className="size-3 motion-safe:animate-spin" /> : null}</span><span className="truncate">{l[item.label]}</span></li>)}
      </ol>
    </div>
  );
}

"use client";

import { createContext, useContext, useMemo } from "react";

/** Locale-aware helpers passed to every label that contains a number. */
export type CrateFormat = {
  locale: string;
  /** 1234 -> "1,234" (en) or "1 234" (fr). */
  number: (value: number) => string;
  /** 30 -> "30s" in en. Other locales use their own short unit format. */
  seconds: (value: number) => string;
  /** Picks a form by Intl plural rules, e.g. plural(n, { one: "source", other: "sources" }). */
  plural: (value: number, forms: Partial<Record<Intl.LDMLPluralRule, string>> & { other: string }) => string;
};

export type CrateLabels = {
  thinking: string;
  stillThinking: string;
  cancel: string;
  responseStreaming: string;
  toolActivity: string;
  runningTool: (toolName: string) => string;
  stalled: string;
  error: string;
  retry: string;
  done: string;
  showThinking: string;
  thoughtFor: (seconds: number, format: CrateFormat) => string;
  reasoningPlaceholder: string;
  sources: string;
  sourceFallback: string;
  sourceTitle: string;
  moreSources: (count: number, format: CrateFormat) => string;
  plan: string;
  planProgress: (current: number, total: number, format: CrateFormat) => string;
  approvalRequired: string;
  approvalTitle: string;
  approvalPreview: string;
  expiresIn: (seconds: number, format: CrateFormat) => string;
  deny: string;
  allow: string;
  queuePosition: (position: number, format: CrateFormat) => string;
  rateLimited: (seconds: number, format: CrateFormat) => string;
  fileUploading: string;
  fileReading: string;
  fileChunking: string;
  fileReady: string;
  fileProgress: (percent: number, format: CrateFormat) => string;
};

export const defaultLabels: CrateLabels = {
  thinking: "Thinking…",
  stillThinking: "Still thinking…",
  cancel: "Cancel",
  responseStreaming: "Response streaming",
  toolActivity: "Agent tool activity",
  runningTool: (toolName) => `Running ${toolName}…`,
  stalled: "Still working…",
  error: "Something went wrong.",
  retry: "Retry",
  done: "Done",
  showThinking: "Show thinking",
  thoughtFor: (seconds, f) => `Thought for ${f.seconds(seconds)}`,
  reasoningPlaceholder: "Working through the details…",
  sources: "Sources",
  sourceFallback: "source",
  sourceTitle: "Source",
  moreSources: (count, f) => `+${f.number(count)} more`,
  plan: "Plan",
  planProgress: (current, total, f) => `${f.number(current)} of ${f.number(total)}`,
  approvalRequired: "Approval required",
  approvalTitle: "The agent wants to send this email",
  approvalPreview: "Review this action before it runs.",
  expiresIn: (seconds, f) => `Expires in ${f.seconds(seconds)}`,
  deny: "Deny",
  allow: "Allow",
  queuePosition: (position, f) => `You’re #${f.number(position)} in line`,
  rateLimited: (seconds, f) => `Slow down. Try again in ${f.seconds(seconds)}`,
  fileUploading: "Upload",
  fileReading: "Reading",
  fileChunking: "Chunking",
  fileReady: "Ready",
  fileProgress: (percent, f) => `${f.number(percent)}%`,
};

export function createFormat(locale: string): CrateFormat {
  const number = new Intl.NumberFormat(locale);
  const seconds = new Intl.NumberFormat(locale, { style: "unit", unit: "second", unitDisplay: "narrow" });
  const plural = new Intl.PluralRules(locale);
  return {
    locale,
    number: (value) => number.format(value),
    seconds: (value) => seconds.format(value),
    plural: (value, forms) => forms[plural.select(value)] ?? forms.other,
  };
}

type CrateContextValue = { labels: CrateLabels; format: CrateFormat };

const CrateContext = createContext<CrateContextValue>({ labels: defaultLabels, format: createFormat("en") });

export type CrateProviderProps = {
  /** Any labels to replace. Missing ones fall back to English. */
  labels?: Partial<CrateLabels>;
  /** BCP 47 locale for numbers, times, and plurals, e.g. "fr" or "ar-EG". Inherited when omitted. */
  locale?: string;
  children: React.ReactNode;
};

/** Sets labels and locale for every crate component inside it. Renders no element. */
export function CrateProvider({ labels, locale, children }: CrateProviderProps) {
  const parent = useContext(CrateContext);
  const resolvedLocale = locale ?? parent.format.locale;
  const value = useMemo(
    () => ({
      labels: { ...parent.labels, ...labels },
      format: resolvedLocale === parent.format.locale ? parent.format : createFormat(resolvedLocale),
    }),
    [parent, labels, resolvedLocale],
  );
  return <CrateContext.Provider value={value}>{children}</CrateContext.Provider>;
}

/** Labels and format for a component: provider values, overridden by the component's own labels prop. */
export function useCrate(overrides?: Partial<CrateLabels>): CrateContextValue {
  const context = useContext(CrateContext);
  return useMemo(
    () => (overrides ? { labels: { ...context.labels, ...overrides }, format: context.format } : context),
    [context, overrides],
  );
}

import type { CrateLabels } from "./crate-provider";

export type AgentStatus =
  | "thinking"
  | "reasoning"
  | "sources"
  | "tool"
  | "plan"
  | "approval"
  | "queue"
  | "file"
  | "streaming"
  | "stalled"
  | "error"
  | "done";

export type AgentSource = {
  id?: string;
  url?: string;
  domain?: string;
  title: string;
};

export type AgentStatusSnapshot = {
  state: AgentStatus;
  activeToolName?: string;
  reasoning?: string;
  sources: AgentSource[];
  elapsedMs: number;
  showCancel: boolean;
  label: string;
  cancel?: () => void;
};

export type WaitStateProps = {
  className?: string;
  accent?: boolean;
  /** Replace any of this component's labels. Overrides CrateProvider. */
  labels?: Partial<CrateLabels>;
};

export function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}
